function showPrompt(text){const v=prompt("Suggested message — edit or copy it as needed:",text);if(v!==null)showToast("Draft ready. Copy it into your institution's approved messaging tool.");}
async function syncTeacherWorkspace(){
 if(!window.LearnixBackend?.enabled) return;
 try{
   cloudCourses=await window.LearnixBackend.listMyCourses();
   const select=$("#assignment-class");
   if(select && cloudCourses.length){select.innerHTML=cloudCourses.map(c=>`<option value="${escapeHtml(c.id)}">${escapeHtml(c.title)}${c.code?` · ${escapeHtml(c.code)}`:""}</option>`).join("");}
   const remote=await window.LearnixBackend.listMyAssignments();
   assignments=remote.map(a=>({id:a.id,title:a.title,className:a.courses?.title||"Course",due:(a.due_at||"").slice(0,10),instructions:a.description||"",status:"published",cloud:true}));
   renderAssignmentRows();
   const hint=document.querySelector(".form-hint"); if(hint)hint.textContent="Connected mode: assignments publish to the shared database and appear for enrolled students.";
   const notice=document.querySelector(".welcome-strip p"); if(notice)notice.textContent="Connected to Learnix shared workspace. Only assigned classes and authorised records are shown.";
 }catch(error){showToast(`Backend sync issue: ${error.message}`);}
}
function renderAssignmentRows(){
 const tbody=$("#assignment-rows");if(!tbody)return;
 const q=($("#assignment-filter")?.value||"").toLowerCase();const statusFilter=$("#assignment-status-filter")?.value||"all";const today=new Date().toISOString().slice(0,10);const all=[...assignments].filter(a=>(a.title+" "+a.className+" "+(a.instructions||"")).toLowerCase().includes(q)).filter(a=>statusFilter==="all"||(statusFilter==="overdue"&&a.due&&a.due<today)||(statusFilter==="upcoming"&&(!a.due||a.due>=today))).sort((a,b)=>(a.due||"").localeCompare(b.due||""));
 const local=all.filter(a=>!a.cloud);const upcoming=assignments.filter(a=>a.due&&a.due>=today).length;const overdue=assignments.filter(a=>a.due&&a.due<today).length;if($("#assignment-total"))$("#assignment-total").textContent=assignments.length;if($("#assignment-upcoming"))$("#assignment-upcoming").textContent=upcoming;if($("#assignment-overdue"))$("#assignment-overdue").textContent=overdue;
 tbody.innerHTML=all.map(a=>{const isOverdue=a.due&&a.due<today;return `<tr><td><b>${escapeHtml(a.title)}</b><br><small>${escapeHtml(a.instructions||"No extra instructions")}</small></td><td>${escapeHtml(a.className)}</td><td>${escapeHtml(formatDate(a.due))}</td><td>—</td><td><span class="table-status" style="background:${isOverdue?"#fff0e9":"#eeecff"};color:${isOverdue?"#b94a22":"#6d61db"}">${a.cloud?"Shared":isOverdue?"Overdue":"Local"}</span></td><td>${a.cloud?'<small>Manage in shared workspace</small>':`<button class="action-button" data-assignment-edit="${escapeHtml(a.id)}">Edit</button> <button class="action-button danger-action" data-assignment-delete="${escapeHtml(a.id)}">Remove</button>`}</td></tr>`}).join("")||`<tr><td colspan="6" class="empty-state">No assignments match. Use “Create assignment” to add your first task.</td></tr>`;
 $$('[data-assignment-edit]',tbody).forEach(b=>b.onclick=()=>{const a=assignments.find(x=>String(x.id)===b.dataset.assignmentEdit);if(!a)return;const title=prompt("Assignment title:",a.title);if(!title?.trim())return;const due=prompt("Due date (YYYY-MM-DD):",a.due||"");if(due===null)return;if(due&&!/^\d{4}-\d{2}-\d{2}$/.test(due)){showToast("Use a valid YYYY-MM-DD date.");return}const className=prompt("Class / subject:",a.className)||a.className;const instructions=prompt("Instructions:",a.instructions||"");if(instructions===null)return;Object.assign(a,{title:title.trim(),due,className:className.trim(),instructions:instructions.trim()});saveStore(storeKey,assignments);renderAssignmentRows();showToast("Assignment updated.")});
 $$('[data-assignment-delete]',tbody).forEach(b=>b.onclick=()=>{const a=assignments.find(x=>String(x.id)===b.dataset.assignmentDelete);if(a&&confirm(`Remove assignment “${a.title}” from this browser?`)){assignments=assignments.filter(x=>String(x.id)!==b.dataset.assignmentDelete);saveStore(storeKey,assignments);renderAssignmentRows();updatePending();showToast("Assignment removed.")}});
}
function formatDate(d){if(!d)return "Not set";const date=new Date(d+"T00:00:00");return date.toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"})}
function openModal(){const modal=$("#modal-backdrop");modal.hidden=false;$("#assignment-title").focus();const date=new Date();date.setDate(date.getDate()+7);$("#assignment-due").min=new Date().toISOString().slice(0,10);$("#assignment-due").value=date.toISOString().slice(0,10)}
